@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{--ink:#11131d;--paper:#f4f0e9;--muted:#878995;--orange:#ff713d;--cyan:#5be3ec;--line:rgba(255,255,255,.13)}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#10121b;color:var(--paper);font-family:'DM Sans',sans-serif}body{background:radial-gradient(ellipse at 50% 35%,#222633 0,#141722 46%,#10121b 100%);overflow-x:hidden}.game-shell{width:min(1240px,calc(100% - 64px));margin:0 auto;padding:24px 0 16px}.topbar{height:46px;display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.brand{display:flex;align-items:center;gap:10px;color:#fff;text-decoration:none;font:800 17px 'Barlow Condensed',sans-serif;letter-spacing:1px}.brand-mark{display:grid;place-items:center;width:30px;height:30px;background:var(--orange);color:#17131a;font:900 20px 'Barlow Condensed';transform:skew(-8deg)}.brand-light{font-weight:500;color:#9da1ad;margin-left:4px}.top-note{font-size:10px;letter-spacing:1.55px;font-weight:700;color:#c5c6ce}.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#ff7549;box-shadow:0 0 12px #ff7044;margin-right:8px}.note-divider{color:#606574;margin:0 8px}.sound-button{display:flex;align-items:center;gap:7px;border:1px solid var(--line);background:#ffffff08;color:#c9cbd2;padding:8px 11px;font:700 9px 'DM Sans';letter-spacing:1px;cursor:pointer}.sound-icon{font-size:15px;color:var(--cyan)}.arena-wrap{position:relative}.arena-frame{position:relative;width:100%;aspect-ratio:16/9;min-height:320px;max-height:690px;overflow:hidden;border:1px solid #5a606b;border-bottom:3px solid #ff713d;background:#171c28;box-shadow:0 24px 65px #0008,inset 0 0 0 1px #fff1}canvas{display:block;width:100%;height:100%;object-fit:cover}.hud{position:absolute;top:20px;left:4.2%;right:4.2%;display:grid;grid-template-columns:1fr 100px 1fr;align-items:start;gap:20px;pointer-events:none}.fighter-card{min-width:0}.fighter-name-row{display:flex;align-items:baseline;gap:10px;margin-bottom:8px}.right-card .fighter-name-row{justify-content:flex-end}.fighter-name{font:900 26px/.9 'Barlow Condensed';letter-spacing:1.4px;color:#fff;text-shadow:0 2px 6px #0009}.fighter-title{font:700 9px 'DM Sans';letter-spacing:1.5px;color:#b1b4c0}.health-track{height:14px;background:#1a1b22;border:1px solid #ffffff50;position:relative;transform:skew(-10deg);overflow:hidden;box-shadow:0 2px 7px #0007}.health-fill{height:100%;width:100%;transition:width .22s ease;background:linear-gradient(90deg,#ff994c,#ff573d);position:relative}.enemy-health{margin-left:auto;background:linear-gradient(90deg,#55e2ec,#2b9fdf)}.enemy-health{float:right}.health-shine{position:absolute;inset:1px;background:linear-gradient(180deg,#fff3,transparent 55%)}.meter-track{height:4px;background:#ffffff20;margin-top:5px;width:62%;transform:skew(-10deg)}.meter-fill{height:100%;width:25%;background:#f8bf60;transition:width .2s}.right-card .meter-track{margin-left:auto}.enemy-meter .meter-fill{float:right;background:#77f0e7}.round-info{text-align:center;margin-top:-3px}.round-label{font:700 8px 'DM Sans';letter-spacing:1.7px;color:#b1b3be}.round-label span{color:#fff}.timer{font:900 36px/.95 'Barlow Condensed';letter-spacing:1px;color:#fff;text-shadow:0 2px 9px #000}.round-status{font:800 8px;letter-spacing:2px;color:#ff855a;margin-top:2px}.arena-caption{position:absolute;bottom:14px;left:20px;right:20px;font:700 8px 'DM Sans';letter-spacing:1.7px;color:#d4d8df;text-shadow:0 1px 5px #000}.arena-caption>span:first-child{color:#ff8051}.caption-right{float:right;color:#c5c8cf}.center-message{position:absolute;z-index:3;inset:0;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;background:linear-gradient(90deg,#080b12b8,#14121a73 50%,#080b12b8);transition:opacity .35s,visibility .35s}.center-message.hidden{opacity:0;visibility:hidden;pointer-events:none}.message-kicker{font:700 10px 'DM Sans';letter-spacing:3.3px;color:#f98a64;margin-bottom:11px}.center-message h1{font:900 clamp(58px,9vw,100px)/.74 'Barlow Condensed';letter-spacing:2px;margin:0;color:#f4efe7;text-shadow:5px 5px 0 #161a23}.center-message h1 em{font-style:normal;color:var(--orange)}.center-message p{font-size:12px;color:#d0d0d4;margin:18px 0 20px}.start-button{height:46px;min-width:212px;background:var(--orange);border:0;color:#17151a;display:flex;align-items:center;justify-content:space-between;padding:0 17px 0 20px;font:900 12px 'DM Sans';letter-spacing:1.2px;cursor:pointer;box-shadow:5px 5px 0 #181923;transition:transform .15s,background .15s}.start-button:hover{background:#ff9669;transform:translate(-2px,-2px)}.start-button b{font-size:21px}.start-hint{margin-top:16px;font:700 8px 'DM Sans';letter-spacing:1.5px;color:#b8bac5}.start-hint kbd{font:700 8px 'DM Sans';color:#fff;border:1px solid #ffffff55;padding:3px 5px;margin:0 2px}.hit-flash{position:absolute;inset:0;pointer-events:none;background:#fff;opacity:0;z-index:2}.hit-flash.flash{animation:flash .2s}@keyframes flash{0%{opacity:.42}100%{opacity:0}}.controls-bar{display:flex;align-items:center;justify-content:space-between;min-height:72px;margin-top:14px;padding:10px 18px;background:#191c27;border:1px solid #ffffff15;box-shadow:0 8px 18px #0002}.control-group{display:flex;align-items:center;gap:7px}.control-label{font:800 8px 'DM Sans';letter-spacing:1.2px;color:#898d9a;margin-right:4px}.control-description{font-size:8px;color:#b7bac4;margin-right:7px;letter-spacing:.5px}.control-group kbd{height:23px;min-width:24px;padding:0 6px;display:grid;place-items:center;background:#292d3a;border:1px solid #ffffff26;border-bottom:2px solid #565b69;color:#fff;font:800 10px 'DM Sans';border-radius:3px}.control-group .special-key{color:#ff9b72;border-color:#a95a415e}.control-divider{height:28px;width:1px;background:#ffffff19;margin:0 10px}.attack-key{color:#8fdef0!important}.restart-button{background:none;color:#bfc1ca;border:0;border-left:1px solid #ffffff1a;padding:8px 0 8px 15px;font:700 9px 'DM Sans';letter-spacing:1px;cursor:pointer}.restart-button span{font-size:15px;margin-right:4px}.mobile-controls{display:none}footer{display:flex;justify-content:space-between;margin:13px 2px 0;color:#747987;font:700 8px 'DM Sans';letter-spacing:1.2px}footer b{color:#ff7444;font-size:12px;margin-left:4px}
@media(max-width:900px){.game-shell{width:calc(100% - 32px);padding-top:16px}.controls-bar{padding:9px 10px}.control-group{gap:5px}.control-description{margin-right:3px}.control-divider{margin:0 5px}.specials-controls .control-label{display:none}.fighter-title{font-size:8px}.hud{grid-template-columns:1fr 72px 1fr;gap:10px}}
@media(max-width:650px){body{min-height:100dvh}.game-shell{width:100%;padding:10px 10px max(10px,env(safe-area-inset-bottom))}.topbar{height:32px;margin-bottom:9px}.brand{font-size:14px;gap:7px}.brand-mark{height:25px;width:25px;font-size:17px}.top-note{font-size:8px;letter-spacing:.8px}.note-divider{margin:0 3px}.sound-button{padding:6px 7px}.sound-label{display:none}.arena-frame{aspect-ratio:4/3;min-height:0;max-height:none}.hud{top:12px;left:3%;right:3%;grid-template-columns:1fr 48px 1fr;gap:6px}.fighter-name{font-size:19px}.fighter-title{font-size:6px;letter-spacing:.8px}.fighter-name-row{gap:5px;margin-bottom:6px}.health-track{height:10px}.round-label{font-size:6px;letter-spacing:1px}.timer{font-size:27px}.round-status{font-size:6px;letter-spacing:1px}.arena-caption{bottom:8px;left:10px;right:10px;font-size:6px}.center-message{padding-top:10px}.message-kicker{font-size:8px;margin-bottom:7px;letter-spacing:2px}.center-message h1{font-size:clamp(54px,16vw,76px)}.center-message p{font-size:10px;margin:12px 0 13px}.start-button{height:38px;min-width:184px;font-size:10px}.start-hint{font-size:7px;margin-top:11px}.controls-bar{display:none}.mobile-controls{display:flex;align-items:center;justify-content:space-between;gap:7px;padding:10px 2px 0}.touch-pad{display:grid;grid-template-columns:repeat(3,38px);gap:3px}.touch-pad button,.touch-actions button{touch-action:none;user-select:none;-webkit-user-select:none;color:#fff;background:#252a38;border:1px solid #ffffff24;border-bottom:2px solid #555b6d;border-radius:4px;font:800 13px 'DM Sans';height:39px}.touch-pad button:nth-child(2){color:#9fe9ed}.touch-actions{display:flex;gap:4px;align-items:center}.touch-actions button{width:47px;font-size:9px}.touch-actions .touch-punch{background:#2b3843;color:#8ee4ef}.touch-actions .touch-kick{background:#3a2f3c;color:#ffb08d}.touch-actions .touch-special{height:39px;width:42px;background:#302a3a;color:#ff9a73;display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:11px}.touch-actions .touch-special span{font-size:6px;letter-spacing:.4px;margin-top:2px;color:#d6bdc2}footer{font-size:6px;margin:10px 2px 0}footer span:last-child{display:none}}
@media(max-width:370px){.top-note{display:none}.touch-actions{gap:3px}.touch-actions button{width:42px}.touch-actions .touch-special{width:37px}.touch-pad{grid-template-columns:repeat(3,34px)}.touch-pad button{height:36px}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const ui = {
    playerHealth: document.getElementById('playerHealth'), enemyHealth: document.getElementById('enemyHealth'),
    playerMeter: document.getElementById('playerMeter'), enemyMeter: document.getElementById('enemyMeter'),
    timer: document.getElementById('timer'), status: document.getElementById('roundStatus'), overlay: document.getElementById('centerMessage'),
    start: document.getElementById('startButton'), restart: document.getElementById('restartButton'), flash: document.getElementById('hitFlash'), sound: document.getElementById('soundToggle')
  };
  const W = 960, H = 540, floor = 440;
  const keys = new Set(), pressed = new Set();
  let running = false, ended = false, soundOn = true, last = 0, elapsed = 0, timer = 60, shake = 0, hitstop = 0, audioCtx = null;
  let particles = [], projectiles = [], player, enemy;

  function makeFighter(name, x, facing, playerSide) {
    return {name, x, y:floor, vx:0, vy:0, facing, hp:100, meter:28, playerSide, grounded:true, action:'idle', actionT:0, cooldown:0, hitTarget:false, invuln:0, flash:0, combo:0, comboT:0, aiT:.5, walkT:0};
  }
  function reset() {
    player = makeFighter('KAI', 300, 1, true); enemy = makeFighter('BRICK', 660, -1, false);
    particles=[];projectiles=[];timer=60;elapsed=0;shake=0;hitstop=0;running=false;ended=false;
    ui.timer.textContent='60';ui.status.textContent='READY';ui.overlay.classList.remove('hidden');ui.start.querySelector('span').textContent='ENTER THE FIGHT';
    updateHud();
  }
  function updateHud() {
    ui.playerHealth.style.width=Math.max(0,player.hp)+'%';ui.enemyHealth.style.width=Math.max(0,enemy.hp)+'%';
    ui.playerMeter.style.width=player.meter+'%';ui.enemyMeter.style.width=enemy.meter+'%';
    ui.timer.textContent=String(Math.ceil(timer)).padStart(2,'0');
  }
  function begin() { if(ended) reset(); running=true;ui.overlay.classList.add('hidden');ui.status.textContent='FIGHT!';playTone(420,.08,'triangle'); }
  function setAction(f, action, duration, cooldown=duration) { f.action=action;f.actionT=duration;f.cooldown=Math.max(f.cooldown,cooldown);f.hitTarget=false; }
  function playTone(freq,duration=.08,type='sine') {
    if(!soundOn)return;
    try { audioCtx ||= new (window.AudioContext||window.webkitAudioContext)(); const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.055,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration); } catch(_){ }
  }
  function emit(x,y,color,count=9,power=1) { for(let i=0;i<count;i++){const a=Math.random()*Math.PI*2,s=(1+Math.random()*4)*power;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-1,life:.3+Math.random()*.38,max:.68,size:2+Math.random()*4,color});} }
  function flash() { ui.flash.classList.remove('flash');void ui.flash.offsetWidth;ui.flash.classList.add('flash'); }
  function hit(attacker, target, damage, knock, color='#fff') {
    if(target.invuln>0)return;
    target.hp=Math.max(0,target.hp-damage);target.invuln=.32;target.flash=.18;target.vx=attacker.facing*knock;target.vy=-2.4;target.grounded=false;
    attacker.meter=Math.min(100,attacker.meter+9);target.meter=Math.min(100,target.meter+4);attacker.combo++;attacker.comboT=1.1;
    emit(target.x,target.y-86,color,16,1.3);shake=7;hitstop=.055;playTone(145+Math.random()*60,.12,'sawtooth');flash();
    if(target.hp<=0)finish(attacker.playerSide);
  }
  function finish(playerWon) {
    if(ended)return;ended=true;running=false;ui.status.textContent=playerWon?'K.O.':'K.O.';
    ui.overlay.classList.remove('hidden');ui.start.querySelector('span').textContent=playerWon?'RUN IT BACK?':'TRY AGAIN';
    ui.overlay.querySelector('.message-kicker').textContent=playerWon?'ROOFTOP LEGEND':'THE NIGHT ISN’T OVER';
    ui.overlay.querySelector('h1').innerHTML=playerWon?'YOU<br><em>WIN</em>':'KNOCK<br><em>OUT</em>';
    ui.overlay.querySelector('p').textContent=playerWon?'Kai owns the skyline. That was clean.':'Brick takes the rooftop. One more round?';
    playTone(playerWon?620:110,.35,'triangle');
  }
  function attack(f, kind) {
    if(!running||f.cooldown>0||f.action==='hurt'||f.action==='dash')return;
    const foe=f===player?enemy:player;
    if(kind==='punch'){setAction(f,'punch',.32,.42);f.meter=Math.min(100,f.meter+2);playTone(300,.04);}
    else if(kind==='kick'){setAction(f,'kick',.48,.61);f.meter=Math.min(100,f.meter+3);playTone(240,.05);}
    else if(kind==='comet'){
      if(f.meter<22)return;f.meter-=22;setAction(f,'cast',.42,.78);
      projectiles.push({x:f.x+f.facing*44,y:f.y-99,vx:f.facing*470,life:2,owner:f,kind:'comet'});emit(f.x+f.facing*38,f.y-102,'#6cf6ff',7,1);playTone(520,.16,'sawtooth');
    } else if(kind==='rise'){
      if(f.meter<32)return;f.meter-=32;setAction(f,'rise',.62,.92);f.vy=-520;f.grounded=false;f.vx=f.facing*60;playTone(380,.2,'triangle');emit(f.x,f.y-55,'#ffb866',12,1.1);
      if(Math.abs(f.x-foe.x)<125)hit(f,foe,20,7,'#ffd178');
    } else if(kind==='blink'){
      if(f.meter<26)return;f.meter-=26;setAction(f,'dash',.32,.72);f.invuln=.3;f.vx=f.facing*590;emit(f.x,f.y-50,f.playerSide?'#63eaf0':'#ff715d',14,1.2);playTone(700,.1,'sine');
    }
  }
  function actKey(k) {
    if(k==='enter'||k===' '){if(!running)begin();return;}
    if(k==='escape'){if(running){running=false;ui.status.textContent='PAUSED';ui.overlay.classList.remove('hidden');ui.start.querySelector('span').textContent='RESUME FIGHT';ui.overlay.querySelector('.message-kicker').textContent='TAKE A BREATH';ui.overlay.querySelector('h1').innerHTML='PAUSE<br><em>BREAK</em>';ui.overlay.querySelector('p').textContent='Your rooftop duel is waiting.';}else if(!ended)begin();return;}
    if(!running)return;
    if(k==='j')attack(player,'punch');if(k==='k')attack(player,'kick');if(k==='q')attack(player,'comet');if(k==='e')attack(player,'rise');if(k==='r')attack(player,'blink');
  }
  window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup',' '].includes(k))e.preventDefault();if(!keys.has(k)){pressed.add(k);actKey(k);}keys.add(k);});
  window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
  window.addEventListener('blur',()=>keys.clear());
  ui.start.addEventListener('click',begin);ui.restart.addEventListener('click',reset);
  ui.sound.addEventListener('click',()=>{soundOn=!soundOn;ui.sound.querySelector('.sound-label').textContent=soundOn?'SOUND ON':'SOUND OFF';ui.sound.querySelector('.sound-icon').textContent=soundOn?'♪':'×';if(soundOn)playTone(500,.06);});
  document.querySelectorAll('[data-key]').forEach(btn=>{const k=btn.dataset.key;const down=e=>{e.preventDefault();if(!keys.has(k)){pressed.add(k);actKey(k);}keys.add(k);btn.classList.add('active');};const up=e=>{e.preventDefault();keys.delete(k);btn.classList.remove('active');};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('pointerleave',up);});

  function update(dt) {
    if(running){elapsed+=dt;timer=Math.max(0,60-elapsed);if(timer<=0){finish(player.hp>=enemy.hp);}
      updateFighter(player,dt,true);updateFighter(enemy,dt,false);updateProjectiles(dt);checkMelee(player,enemy);checkMelee(enemy,player);updateAI(dt);
      if(player.comboT>0)player.comboT-=dt;if(enemy.comboT>0)enemy.comboT-=dt;
    }
    particles=particles.filter(p=>p.life>0);particles.forEach(p=>{p.life-=dt;p.x+=p.vx*dt*60;p.y+=p.vy*dt*60;p.vy+=.12;});
    if(shake>0)shake=Math.max(0,shake-dt*32);if(hitstop>0)hitstop-=dt;updateHud();pressed.clear();
  }
  function updateFighter(f,dt,isPlayer) {
    if(f.cooldown>0)f.cooldown-=dt;if(f.invuln>0)f.invuln-=dt;if(f.flash>0)f.flash-=dt;
    if(f.actionT>0){f.actionT-=dt;if(f.actionT<=0&&['punch','kick','cast','rise','dash','hurt'].includes(f.action)){f.action='idle';f.actionT=0;}}
    if(isPlayer){const frozen=['punch','kick','cast','rise','hurt'].includes(f.action);if(!frozen){let speed=235;if(keys.has('a')||keys.has('arrowleft')){f.vx=-speed;f.facing=-1;f.walkT+=dt*10;}else if(keys.has('d')||keys.has('arrowright')){f.vx=speed;f.facing=1;f.walkT+=dt*10;}else if(f.action!=='dash'){f.vx*=Math.pow(.001,dt);if(Math.abs(f.vx)<8)f.vx=0;}
        if((keys.has('w')||keys.has('arrowup'))&&f.grounded&&f.action!=='dash'){f.vy=-510;f.grounded=false;f.action='jump';playTone(260,.06);}
      }}
    f.x+=f.vx*dt;f.y+=f.vy*dt;f.vy+=1450*dt;
    if(f.y>=floor){f.y=floor;f.vy=0;f.grounded=true;if(f.action==='jump')f.action='idle';}
    f.x=Math.max(55,Math.min(W-55,f.x));
  }
  function checkMelee(a,b) {
    if(a.hitTarget||a.actionT<=0)return;
    let range=0,damage=0,window=false,knock=4,color='#fff';
    if(a.action==='punch'){range=95;damage=8;window=a.actionT<.21&&a.actionT>.07;knock=3.5;color='#d8fbff';}
    if(a.action==='kick'){range=119;damage=13;window=a.actionT<.30&&a.actionT>.11;knock=5;color='#ffc28c';}
    if(window&&Math.abs(a.x-b.x)<range&&Math.abs((a.y-85)-(b.y-85))<95&&a.facing===Math.sign(b.x-a.x)){a.hitTarget=true;hit(a,b,damage,knock,color);}
  }
  function updateProjectiles(dt) {
    projectiles=projectiles.filter(p=>p.life>0);
    for(const p of projectiles){p.x+=p.vx*dt;p.life-=dt;const foe=p.owner===player?enemy:player;if(Math.abs(p.x-foe.x)<34&&Math.abs(p.y-(foe.y-90))<54){hit(p.owner,foe,16,6,p.kind==='comet'?'#65f7ff':'#ff7755');p.life=0;emit(p.x,p.y,'#b7ffff',18,1.5);} }
  }
  function updateAI(dt) {
    if(!running||enemy.hp<=0)return;const d=player.x-enemy.x,ad=Math.abs(d);enemy.facing=d<0?-1:1;enemy.aiT-=dt;
    if(enemy.action==='hurt'||['punch','kick','cast','rise','dash'].includes(enemy.action))return;
    if(enemy.aiT>0)return;enemy.aiT=.28+Math.random()*.32;
    if(ad>190){if(Math.random()<.2&&enemy.meter>22)attack(enemy,'comet');else{enemy.vx=Math.sign(d)*145;enemy.action='idle';}}
    else if(ad>110){enemy.vx=Math.sign(d)*110;if(Math.random()<.45)attack(enemy,'kick');}
    else {enemy.vx=0;const r=Math.random();if(r<.42)attack(enemy,'punch');else if(r<.76)attack(enemy,'kick');else if(enemy.meter>32)attack(enemy,'rise');else if(Math.random()<.5)enemy.vx=-Math.sign(d)*120;}
  }

  function drawBackground() {
    const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#111925');g.addColorStop(.42,'#33243c');g.addColorStop(.72,'#b64750');g.addColorStop(1,'#e56b4f');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
    // moon and atmospheric glow
    const glow=ctx.createRadialGradient(690,147,8,690,147,210);glow.addColorStop(0,'#ffd79a44');glow.addColorStop(1,'#ffbd8500');ctx.fillStyle=glow;ctx.fillRect(440,0,500,370);
    ctx.fillStyle='#ffddb7';ctx.beginPath();ctx.arc(690,132,46,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ed8a7370';ctx.fillRect(0,286,W,2);
    // far skyline
    for(let i=0;i<17;i++){let x=i*64-14,w=43+(i%3)*8,h=90+(i*47%120),y=330-h;ctx.fillStyle=i%2?'#202337':'#252237';ctx.fillRect(x,y,w,h);ctx.fillStyle='#f6a66a';for(let wy=y+14;wy<326;wy+=19)for(let wx=x+8;wx<x+w-5;wx+=13)if(((wx+wy+i)%4)<2){ctx.globalAlpha=.22+((i+wy)%3)*.08;ctx.fillRect(wx,wy,4,7);}ctx.globalAlpha=1;}
    // signature neon signs
    sign(72,235,105,45,'HOTEL','NEON');sign(782,215,112,58,'NO SLEEP','CITY');
    // close rooftops
